WITH deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY quantity DESC NULLS FIRST, id) AS rank_in_group FROM order_items) ranked WHERE rank_in_group = 1) SELECT CASE WHEN unit_price >= 420 THEN 'LARGE' ELSE 'SMALL' END AS unit_price_tier, CASE WHEN quantity >= 9 THEN 'HIGH' ELSE 'LOW' END AS quantity_tier, SUM(quantity) AS total_quantity, MIN(quantity) AS min_quantity, COUNT(*) AS event_count, BIT_AND(quantity) AS quantity_bit_and, BIT_AND(quantity) AS quantity_bit_and_2 FROM deduped GROUP BY CASE WHEN unit_price >= 420 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN quantity >= 9 THEN 'HIGH' ELSE 'LOW' END ORDER BY quantity_tier DESC
